 static object State(Table t){var cells=new List<object>();for(int r=0;r<t.Rows.Count;r++)for(int c=0;c<t.Columns.Count;c++){var x=t.Cells[r,c];var range=x.GetMergeRange();cells.Add(new{r,c,data=Data(x),height=x.TextHeight,style=H(x.TextStyleId),alignment=x.Alignment.ToString(),contents=x.Contents.Cast<CellContent>().Select(q=>new{block=H(q.BlockTableRecordId),auto=q.IsAutoScale,scale=q.Scale,rotation=q.Rotation,color=q.ContentColor.ToString(),style=H(q.TextStyleId),height=q.TextHeight}).ToArray(),merge=range==null||range.IsNull?null:new[]{range.TopRow,range.LeftColumn,range.BottomRow,range.RightColumn}});}return new{handle=t.Handle.ToString(),geometry=Stable(t,false),row_heights=Enumerable.Range(0,t.Rows.Count).Select(r=>t.Rows[r].Height).ToArray(),column_widths=Enumerable.Range(0,t.Columns.Count).Select(c=>t.Columns[c].Width).ToArray(),cells};}
