   try{mutation();foreach(var i in items){var t=Open(db,tr,i);var data=new string[i.row_count,i.column_count];for(int r=0;r<i.row_count;r++)for(int c=0;c<i.column_count;c++)data[r,c]=J.Serialize(Data(t.Cells[r,c]));var stable=Stable(t,i.position!=null);bool title=TitleMerged(t);var fitRows=new List<object>();var fitScales=new Dictionary<string,double>();var style=i.text_style==null?ObjectId.Null:((TextStyleTable)tr.GetObject(db.TextStyleTableId,OpenMode.ForRead))[i.text_style];t.UpgradeOpen();if(title)t.UnmergeCells(CellRange.Create(t,0,0,0,i.column_count-1));
